<?php declare(strict_types=1);
use Kulturhus\Verein\{ContributionInvoices,ContributionReminders,ContributionMail,MailPolicy,Permissions};
use Kulturhus\Verein\Finance\Contributions\{ContributionRunInput,ContributionRunRequests};
use Kulturhus\Native\Shared\Db;

final class OwnContributionCommitLoss extends PDO
{
    public bool $loseNext=false;
    public function commit():bool{$lose=$this->loseNext;$result=parent::commit();if($lose){$this->loseNext=false;throw new PDOException('Own actual contribution COMMIT acknowledgement lost.');}return$result;}
}

/** Real independent readers, payment writes, commit acknowledgement loss and NOWAIT locks. */
function ownContributionRunFailures(PDO $db,callable $check,array $f,array $config):array
{
    $name=(string)$db->query('SELECT DATABASE()')->fetchColumn();if(!preg_match('/\Akh_(?:test|native)_[a-f0-9]{24}\z/D',$name)||!in_array((int)$config['port'],[13371,13372],true)||$config['host']!=='127.0.0.1')throw new RuntimeException('Owned contribution failure database required.');
    $dsn='mysql:host=127.0.0.1;port='.$config['port'].';dbname='.$name.';charset=utf8mb4';$options=[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false];$caller=new PDO($dsn,$config['username'],$config['password'],$options);$loss=new OwnContributionCommitLoss($dsn,$config['username'],$config['password'],$options);
    $today=ContributionRunInput::today();$input=['data'=>['day'=>$today]];$requests=$f['requests'];$finance=$f['finance'];$deny=$f['deny'];$tables=$f['tables'];$payer=$f['payer'];$club=$f['club'];$actor=$f['actor'];
    try{
        $payer('own-current-payment');$entry=$finance->createAnnualContribution('own-current-payment',2026,'','2026-01-01');(new ContributionInvoices($db,$actor))->issue($entry);
        $caller->beginTransaction();$caller->query('SELECT COUNT(*) FROM finance_allocations')->fetchColumn();$finance->recordPayment($entry,(int)$finance->entry($entry)['version'],$f['account'],'2026-02-01','20.00');$afterPayment=ownOriginalDatabaseHash($db,$tables);
        $oldPreview=(new ContributionReminders($caller,$actor))->preview($today);$offered=array_values(array_filter($oldPreview['reminders'],static fn(array$row):bool=>$row['entry_id']===$entry));$mail=ContributionMail::build($caller,$club,$entry,'reminder');
        $check(count($offered)===1&&$offered[0]['remaining_cents']===2800&&str_contains($mail['text'],'Offener Betrag: 28,00 €')&&!str_contains($mail['text'],'Offener Betrag: 48,00 €'),'actual older contribution caller reads the real later partial payment in both the reminder plan and actual message');$caller->rollBack();$check(ownOriginalDatabaseHash($db,$tables)===$afterPayment,'current contribution balance and message reads preserve every complete paid original row');
        $review=$requests->prepare($input);$caller->beginTransaction();$caller->query('SELECT COUNT(*) FROM finance_allocations')->fetchColumn();$finance->recordPayment($entry,(int)$finance->entry($entry)['version'],$f['account'],'2026-02-01','28.00');$paid=ownOriginalDatabaseHash($db,$tables);$oldWorker=(new ContributionReminders($caller,$actor))->preview($today);$check(!array_filter($oldWorker['reminders'],static fn(array$row):bool=>$row['entry_id']===$entry),'actual older contribution snapshot never offers a genuinely fully paid invoice');$rejectedKey=($f['key'])();$deny(fn()=>(new ContributionRunRequests($caller,$actor))->accept($input,$rejectedKey,$review['hash'],true),409,'actual full payment after contribution review rejects an obsolete scheduling approval');$caller->rollBack();$deny(fn()=>$requests->receipt($rejectedKey),404,'rejected paid contribution schedule has no invented private first');$check(ownOriginalDatabaseHash($db,$tables)===$paid,'obsolete paid contribution rejection changes no entire earlier financial row');

        $roleVersion=(int)Db::run($db,'SELECT version FROM settings_roles WHERE club_id=? AND id=?',[$club,$f['financeRole']])->fetchColumn();$caller->beginTransaction();$caller->query('SELECT COUNT(*) FROM settings_roles')->fetchColumn();$f['settings']->saveRole($f['financeRole'],$roleVersion,array_replace($f['financeRoleData'],['finance_access'=>'none']));$revoked=ownOriginalDatabaseHash($db,$tables);$deny(fn()=>(new ContributionRunRequests($caller,$actor))->receipt($f['first']['key']),403,'actual withdrawn contribution reading denies a known own first behind an older role snapshot');$caller->rollBack();$check(ownOriginalDatabaseHash($db,$tables)===$revoked,'withdrawn contribution role read preserves every entire current row');$f['settings']->saveRole($f['financeRole'],$roleVersion+1,$f['financeRoleData']);

        $payer('own-commit-loss');$lossEntry=$finance->createAnnualContribution('own-commit-loss',2026,'','2026-01-01');(new ContributionInvoices($db,$actor))->issue($lossEntry);$lossActor='own-contribution-other';$lossRequests=new ContributionRunRequests($loss,$lossActor);$lossReview=$lossRequests->prepare($input);$lossKey=($f['key'])();$loss->loseNext=true;$lost=false;try{$lossRequests->accept($input,$lossKey,$lossReview['hash'],true);}catch(PDOException$failure){if($failure->getMessage()!=='Own actual contribution COMMIT acknowledgement lost.')throw$failure;$lost=true;}
        $otherRequests=new ContributionRunRequests($db,$lossActor);$lossFirst=$otherRequests->receipt($lossKey);$check($lost&&!$loss->inTransaction()&&$lossFirst['result']['queued']===1&&$lossFirst['result']['deliveries'][0]['entry_id']===$lossEntry,'actual contribution COMMIT succeeds before its response is lost and retains the real durable one-job first');$committed=ownOriginalDatabaseHash($db,$tables);$check($lossRequests->accept($input,$lossKey,$lossReview['hash'],true)===$lossFirst&&ownOriginalDatabaseHash($db,$tables)===$committed,'lost contribution commit replay reads exact first bytes without repeating any complete business row');$deny(fn()=>$requests->receipt($lossKey),404,'another Finance author never inherits the actual lost-response personal contribution first');

        $payer('own-busy-payer');$busyEntry=$finance->createAnnualContribution('own-busy-payer',2026,'','2026-01-01');(new ContributionInvoices($db,$actor))->issue($busyEntry);$busyReview=$requests->prepare($input);$beforeBusy=ownOriginalDatabaseHash($db,$tables);$caller->beginTransaction();Db::run($caller,'SELECT * FROM clubs WHERE id=? FOR UPDATE',[$club])->fetch();$deny(fn()=>$requests->accept($input,($f['key'])(),$busyReview['hash'],true),503,'real independent club writer produces a precise busy contribution result without a partial order');$caller->rollBack();$check(ownOriginalDatabaseHash($db,$tables)===$beforeBusy,'busy contribution approval retains every complete earlier original and delivery');
        $caller->beginTransaction();Db::run($caller,'SELECT * FROM finance_entries WHERE club_id=? AND id=? FOR UPDATE',[$club,$busyEntry])->fetch();$deny(fn()=>(new ContributionReminders($db,$actor))->preview($today),503,'real locked payment source cannot be silently classified as a blocked paid contribution');$caller->rollBack();

        $pending=Db::run($db,"SELECT * FROM contribution_deliveries WHERE club_id=? AND status='pending' ORDER BY id",[$club])->fetchAll();$check(count($pending)>=3,'actual pending contribution orders exist before transient worker locking proof');$variables=['APP_URL','APP_ENV','VEREIN_MODE','KULTURHUS_DISABLE_MAIL','KULTURHUS_LOCAL_DEMO'];$originalEnv=[];foreach($variables as$variable){$originalEnv[$variable]=getenv($variable);putenv($variable);}
        try{
            $check(MailPolicy::allowed('https://owned-contribution.example.invalid'),'worker locking proof reaches actual delivery policy with an explicit in-memory callback only');$caller->beginTransaction();foreach($pending as$row)Db::run($caller,'SELECT * FROM finance_entries WHERE club_id=? AND id=? FOR UPDATE',[$club,$row['entry_id']])->fetch();$workerBefore=ownOriginalDatabaseHash($db,$tables);$calls=0;$sent=(new ContributionReminders($db,$actor))->dispatch('https://owned-contribution.example.invalid',static function()use(&$calls):bool{++$calls;return true;},$today);$caller->rollBack();$check($sent===0&&$calls===0&&ownOriginalDatabaseHash($db,$tables)===$workerBefore,'known transient contribution source locks leave every actual pending order unchanged and invoke no callback');
        }finally{if($caller->inTransaction())$caller->rollBack();foreach($originalEnv as$variable=>$value)putenv($value===false?$variable:$variable.'='.$value);}
        $check($requests->receipt($f['first']['key'])===$f['first']&&$otherRequests->receipt($lossKey)===$lossFirst,'later payment role and lock changes retain both entire genuinely earlier scheduling firsts');
        return compact('lossFirst','lossEntry','busyEntry','entry');
    }finally{if($caller->inTransaction())$caller->rollBack();if($loss->inTransaction())$loss->rollBack();}
}
